// planningLongEntry stretches one agenda row far enough to force the time
// column and the title to compete, which is where a two-column agenda row
// breaks if it is going to.
func planningLongEntry(gc GalleryContext) string {
	if gc.LongContent {
		return "Workshop: agreeing the visibility timeout and dead-letter policy for every persisted job kind before the batched claim change ships"
	}
	return "Queue latency workshop"
}

